mod root;
mod fast;
#[path="../setup/fast.rs"]mod reference;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve};
fn prime(n:u64)->bool{n>=2&&(2..).take_while(|d|d*d<=n).all(|d|n%d!=0)}
fn main(){counted::disable();let(mut qualified,mut calls)=(0,0);for p in 3..=1000{if !prime(p){continue}let f=Fp::new(p);for n in[4,5,7,9]{if (p-1)%n!=0{continue}let z=root::reference(&f,n);assert_eq!(root::power_map(&f,n).0,z);qualified+=1;}}
println!("stage\tp\tn\tc\trep\tarm\tz\ttrials\tcounts");for p in[101,113,251,421,601,1009,4001,10009]{assert!(prime(p));let f=Fp::new(p);for n in[4,5,7,9]{if(p-1)%n!=0{continue}let expected=root::reference(&f,n);let mut prior=std::collections::BTreeMap::new();for rep in 0..2{for i in 0..2{let arm=if rep==0{i}else{1-i};counted::reset();let(z,trials)=if arm==0{(root::reference(&f,n),0)}else{root::power_map(&f,n)};let counts=counted::snapshot();counted::disable();assert_eq!(z,expected);let sig=(z,trials,counts.clone());if rep==1{assert_eq!(prior[&arm],sig);}else{prior.insert(arm,sig);}for(modulus,v)in counts{assert_eq!(modulus,p);assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("root\t{p}\t{n}\t0\t{rep}\t{arm}\t{z}\t{trials}\t{}",v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}}
for(p,c,g)in[(101,2,2),(251,18,2),(601,7,2),(113,3,3),(421,2,3),(19,2,4),(37,2,4),(73,2,4)]{let n=2*g+1;let mut coeff=vec![0;n+1];coeff[0]=c;coeff[n]=1;let curve=Curve::new(Fp::new(p),Poly::from_coeffs(&coeff));let expected=reference::prepare(&curve);let mut prior=std::collections::BTreeMap::new();for rep in 0..2{for i in 0..2{let arm=if rep==0{i}else{1-i};counted::reset();let out=if arm==0{reference::prepare(&curve)}else{fast::prepare(&curve)};let counts=counted::snapshot();counted::disable();assert_eq!(out,expected);let sig=(out.clone(),counts.clone());if rep==1{assert_eq!(prior[&arm],sig);}else{prior.insert(arm,sig);}for(modulus,v)in counts{assert_eq!(modulus,p);assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("full\t{p}\t{n}\t{c}\t{rep}\t{arm}\t{}\t0\t{}",out.1,v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}
eprintln!("exhaustive_prime_field_pairs={qualified} calls={calls} exact_canonical_root_full_FB_and_character_outputs=true exact_repeats=true isolated_root_and_full_setup_only=true");}
